import pandas as pd
import numpy as np

def verify():
    md_path = '/root/.gemini/skills/lab-unit-harmonization/reference/ckd_lab_features.md'
    output_path = '/root/ckd_lab_data_harmonized.csv'

    # Extract ranges again
    reference_ranges = {}
    with open(md_path, 'r') as f:
        lines = f.readlines()
    for line in lines:
        if line.startswith('|') and 'Key' not in line and '---' not in line:
            parts = [p.strip() for p in line.split('|')]
            if len(parts) >= 8:
                key = parts[1]
                try:
                    min_val = float(parts[4])
                    max_val = float(parts[5])
                    reference_ranges[key] = (min_val, max_val)
                except:
                    continue

    df = pd.read_csv(output_path)
    lab_cols = [c for c in df.columns if c != 'patient_id']

    out_of_range = []

    for col in lab_cols:
        if col in reference_ranges:
            min_val, max_val = reference_ranges[col]
            # 5% tolerance
            lower = min_val * 0.95
            upper = max_val * 1.05

            vals = df[col].astype(float)
            bad = vals[(vals < lower) | (vals > upper)]
            if len(bad) > 0:
                out_of_range.append((col, len(bad), bad.min(), bad.max(), min_val, max_val))

    if not out_of_range:
        print("All labs within range (with 5% tolerance).")
    else:
        print("Out of range features:")
        for col, count, bmin, bmax, rmin, rmax in out_of_range:
            print(f"{col}: {count} values out of range. Range: [{rmin}, {rmax}], Found: [{bmin}, {bmax}]")

    # Check format
    print("\nChecking format (X.XX):")
    with open(output_path, 'r') as f:
        lines = f.readlines()[1:6] # first 5 rows
        for line in lines:
            print(line.strip())

verify()
